import { Fragment, NodeRange, Slice } from 'prosemirror-model'
import type { Command, Transaction } from 'prosemirror-state'
import { ReplaceAroundStep } from 'prosemirror-transform'

import { withAutoFixList } from '../utils/auto-fix-list'
import {
  atEndBlockBoundary,
  atStartBlockBoundary,
} from '../utils/block-boundary'
import { getListType } from '../utils/get-list-type'
import { isListNode } from '../utils/is-list-node'
import { findListsRange, isListsRange } from '../utils/list-range'
import { mapPos } from '../utils/map-pos'
import { safeLift } from '../utils/safe-lift'
import { zoomInRange } from '../utils/zoom-in-range'

import { withVisibleSelection } from './set-safe-selection'

/**
 * @public
 *
 * @group Commands
 */
export interface DedentListOptions {
  /**
   * A optional from position to indent.
   *
   * @defaultValue `state.selection.from`
   */
  from?: number

  /**
   * A optional to position to indent.
   *
   * @defaultValue `state.selection.to`
   */
  to?: number

  /**
   * When `true`, the command never leaves a list node whose first child is a
   * list node (a list node with a hidden marker). The blocks after the
   * dedented block move one level up with it instead of keeping their depth
   * inside such a node, so a block is never more than one level deeper than
   * the block before it.
   *
   * @defaultValue `false`
   */
  strict?: boolean
}

/**
 * Returns a command function that decreases the indentation of selected list nodes.
 *
 * @public
 *
 * @group Commands
 */
export function createDedentListCommand(options?: DedentListOptions): Command {
  const dedentListCommand: Command = (state, dispatch): boolean => {
    const tr = state.tr

    const $from =
      options?.from == null ? tr.selection.$from : tr.doc.resolve(options.from)
    const $to =
      options?.to == null ? tr.selection.$to : tr.doc.resolve(options.to)

    const range = findListsRange($from, $to)
    if (!range) return false

    const strict = options?.strict ?? false
    if (dedentRange(range, tr, strict)) {
      dispatch?.(tr)
      return true
    }
    return false
  }

  return withVisibleSelection(withAutoFixList(dedentListCommand))
}

function dedentRange(
  range: NodeRange,
  tr: Transaction,
  strict: boolean,
  startBoundary?: boolean,
  endBoundary?: boolean,
): boolean {
  const { depth, $from, $to } = range

  startBoundary = startBoundary || atStartBlockBoundary($from, depth + 1)

  if (!startBoundary) {
    const { startIndex, endIndex } = range
    if (endIndex - startIndex === 1) {
      const contentRange = zoomInRange(range)
      return contentRange ? dedentRange(contentRange, tr, strict) : false
    } else {
      return splitAndDedentRange(range, tr, strict, startIndex + 1)
    }
  }

  endBoundary = endBoundary || atEndBlockBoundary($to, depth + 1)

  if (!endBoundary) {
    fixEndBoundary(range, tr, strict)
    const endOfParent = $to.end(depth)
    range = new NodeRange(
      tr.doc.resolve($from.pos),
      tr.doc.resolve(endOfParent),
      depth,
    )
    return dedentRange(range, tr, strict, undefined, true)
  }

  if (
    range.startIndex === 0 &&
    range.endIndex === range.parent.childCount &&
    isListNode(range.parent)
  ) {
    return dedentNodeRange(new NodeRange($from, $to, depth - 1), tr, strict)
  }

  return dedentNodeRange(range, tr, strict)
}

/**
 * Split a range into two parts, and dedent them separately.
 */
function splitAndDedentRange(
  range: NodeRange,
  tr: Transaction,
  strict: boolean,
  splitIndex: number,
): boolean {
  const { $from, $to, depth } = range

  const splitPos = $from.posAtIndex(splitIndex, depth)

  const range1 = $from.blockRange(tr.doc.resolve(splitPos - 1))
  if (!range1) return false

  const getRange2From = mapPos(tr, splitPos + 1)
  const getRange2To = mapPos(tr, $to.pos)

  dedentRange(range1, tr, strict, undefined, true)

  let range2 = tr.doc
    .resolve(getRange2From())
    .blockRange(tr.doc.resolve(getRange2To()))

  if (range2 && range2.depth >= depth) {
    range2 = new NodeRange(range2.$from, range2.$to, depth)
    dedentRange(range2, tr, strict, true, undefined)
  }
  return true
}

export function dedentNodeRange(
  range: NodeRange,
  tr: Transaction,
  strict: boolean,
) {
  if (isListNode(range.parent)) {
    return safeLiftRange(tr, range, strict)
  } else if (isListsRange(range)) {
    return dedentOutOfList(tr, range)
  } else {
    return safeLiftRange(tr, range, strict)
  }
}

function safeLiftRange(
  tr: Transaction,
  range: NodeRange,
  strict: boolean,
): boolean {
  if (strict && planTrailingSiblings(range) === TrailingSiblings.Hide) {
    // Lift the trailing siblings together with the range, so they move one
    // level up instead of keeping their depth inside a hidden wrapper.
    const endOfParent = range.$to.end(range.depth)
    range = new NodeRange(range.$from, tr.doc.resolve(endOfParent), range.depth)
    return safeLift(tr, range)
  }
  if (moveRangeSiblings(tr, range)) {
    const $from = tr.doc.resolve(range.$from.pos)
    const $to = tr.doc.resolve(range.$to.pos)
    range = new NodeRange($from, $to, range.depth)
  }
  return safeLift(tr, range)
}

/**
 * What happens to the siblings after a range when the range is lifted out of
 * its parent list node.
 */
const enum TrailingSiblings {
  /** There are no siblings after the range. */
  None,
  /** They become children of the last item in the range. */
  Append,
  /**
   * They are wrapped in a new list node to keep their depth. The new node
   * shows a marker, because its first child is not a list node.
   */
  Wrap,
  /**
   * Like `Wrap`, but the new node hides its marker, because its first child
   * is a list node.
   */
  Hide,
}

function planTrailingSiblings(range: NodeRange): TrailingSiblings {
  const { $to, depth, end, parent, endIndex } = range
  if (end >= $to.end(depth)) return TrailingSiblings.None

  const lastChild = parent.maybeChild(endIndex - 1)
  if (!lastChild) return TrailingSiblings.None

  const canAppend = lastChild.canReplace(
    lastChild.childCount,
    lastChild.childCount,
    parent.content,
    endIndex,
    parent.childCount,
  )
  if (canAppend) return TrailingSiblings.Append

  return isListNode(parent.child(endIndex))
    ? TrailingSiblings.Hide
    : TrailingSiblings.Wrap
}

function moveRangeSiblings(tr: Transaction, range: NodeRange): boolean {
  const plan = planTrailingSiblings(range)
  if (plan === TrailingSiblings.None) return false

  const listType = getListType(tr.doc.type.schema)
  const { $to, depth, end } = range
  const endOfParent = $to.end(depth)

  if (plan === TrailingSiblings.Append) {
    tr.step(
      new ReplaceAroundStep(
        end - 1,
        endOfParent,
        end,
        endOfParent,
        new Slice(Fragment.from(listType.create(null)), 1, 0),
        0,
        true,
      ),
    )
  } else {
    tr.step(
      new ReplaceAroundStep(
        end,
        endOfParent,
        end,
        endOfParent,
        new Slice(Fragment.from(listType.create(null)), 0, 0),
        1,
        true,
      ),
    )
  }
  return true
}

function fixEndBoundary(
  range: NodeRange,
  tr: Transaction,
  strict: boolean,
): void {
  if (range.endIndex - range.startIndex >= 2) {
    range = new NodeRange(
      range.$to.doc.resolve(
        range.$to.posAtIndex(range.endIndex - 1, range.depth),
      ),
      range.$to,
      range.depth,
    )
  }

  const contentRange = zoomInRange(range)
  if (contentRange) {
    fixEndBoundary(contentRange, tr, strict)
    range = new NodeRange(
      tr.doc.resolve(range.$from.pos),
      tr.doc.resolve(range.$to.pos),
      range.depth,
    )
  }

  // In strict mode, keep the trailing siblings where they are. They stay
  // inside the outer item that is lifted, so they move one level up with it
  // instead of keeping their depth inside a hidden wrapper.
  if (strict && planTrailingSiblings(range) === TrailingSiblings.Hide) return

  moveRangeSiblings(tr, range)
}

export function dedentOutOfList(tr: Transaction, range: NodeRange): boolean {
  const { startIndex, endIndex, parent } = range

  const getRangeStart = mapPos(tr, range.start)
  const getRangeEnd = mapPos(tr, range.end)

  // Merge the list nodes into a single big list node
  for (let end = getRangeEnd(), i = endIndex - 1; i > startIndex; i--) {
    end -= parent.child(i).nodeSize
    tr.delete(end - 1, end + 1)
  }

  const $start = tr.doc.resolve(getRangeStart())
  const listNode = $start.nodeAfter

  if (!listNode) return false

  const start = range.start
  const end = start + listNode.nodeSize

  if (getRangeEnd() !== end) return false

  if (
    !$start.parent.canReplace(
      startIndex,
      startIndex + 1,
      Fragment.from(listNode),
    )
  ) {
    return false
  }

  tr.step(
    new ReplaceAroundStep(
      start,
      end,
      start + 1,
      end - 1,
      new Slice(Fragment.empty, 0, 0),
      0,
      true,
    ),
  )
  return true
}
